type EntryRow = {
  key: string;
  deleted: number;
  etag: string | null;
  hash: string | null;
  metadata: string;
  content: number;
};

function grantOf(
  cid: string | null,
  bytes: Uint8Array | null,
  audience: string | null,
  issuer: string | null,
  nbf: number | null,
  exp: number | null,
): GrantRecord | null {
  if (cid === null || bytes === null || audience === null || issuer === null) return null;
  return { cid, bytes: new Uint8Array(bytes), audience, issuer, notBefore: nbf, expiresAt: exp };
}

function entryOf(row: EntryRow): LocalEntry {
  if (row.deleted === 1) return { key: row.key, deleted: true };
  return {
    key: row.key,
    deleted: false,
    etag: row.etag!,
    hash: row.hash!,
    metadata: JSON.parse(row.metadata) as Record<string, string>,
    content: row.content === 1,
  };
}

function storageError(error: unknown, action: string): ReplicaError {
  if (isReplicaError(error)) return error;
  const code = errnoOf(error);
  const message = error instanceof Error ? error.message : String(error);
  if (code === "ENOSPC" || code === "EDQUOT" || /SQLITE_FULL|database or disk is full/i.test(`${String(code)} ${message}`)) {
    return new ReplicaError(ReplicaErrorCode.STORAGE_FULL, `${action}: the local disk is full.`, undefined, { cause: error });
  }
  return new ReplicaError(ReplicaErrorCode.STORAGE_ERROR, `${action}: ${message}`, undefined, { cause: error });
}

const isHash = (name: string) => /^[0-9a-f]{64}$/.test(name);

function errnoOf(error: unknown): unknown {
  return typeof error === "object" && error !== null && "code" in error ? error.code : undefined;
}


/** A directory's entries; only a directory that does not exist is empty. */
const isShard = (name: string) => /^[0-9a-f]{2}$/.test(name);
const isTempName = (name: string) => /^[0-9a-f]{64}\.[0-9a-f]{12}$/.test(name);

/**
 * The files the writer itself creates under a replica's `blobs/`: `<2 hex>/<64 hex>` blobs (the
 * shard is the hash's first two characters) and `.tmp/<64 hex>.<12 hex>` temp files. Only regular
 * files inside real directories qualify; symlinks, stray files, unknown names and anything else
 * are skipped, never followed, counted or deleted. A missing or non-directory `root` is empty.
 */
async function writerBlobFiles(root: string): Promise<Array<{ path: string; hash: string | null; size: number }>> {
  const out: Array<{ path: string; hash: string | null; size: number }> = [];
  let shards;
  try {
    shards = await readdir(root, { withFileTypes: true });
  } catch (error) {
    if (errnoOf(error) === "ENOENT" || errnoOf(error) === "ENOTDIR") return out;
    throw error;
  }
  for (const shard of shards) {
    const temp = shard.name === ".tmp";
    if (!shard.isDirectory() || !(temp || isShard(shard.name))) continue;
    const shardPath = join(root, shard.name);
    let files;
    try {
      files = await readdir(shardPath, { withFileTypes: true });
    } catch (error) {
      if (errnoOf(error) === "ENOENT" || errnoOf(error) === "ENOTDIR") continue;
      throw error;
    }
    for (const file of files) {
      if (!file.isFile()) continue;
      const ok = temp ? isTempName(file.name) : isHash(file.name) && file.name.startsWith(shard.name);
      if (!ok) continue;
      const path = join(shardPath, file.name);
      const info = await lstat(path).catch(() => undefined);
      if (!info?.isFile()) continue;
      out.push({ path, hash: temp ? null : file.name, size: info.size });
    }
  }
  return out;
}

/** Unlink every writer-created blob under `root` not in `keep`, and every writer temp file. Foreign entries are left alone. */
async function unlinkWriterOrphans(root: string, keep: Set<string>): Promise<number> {
  let removed = 0;
  const touched = new Set<string>();
  for (const file of await writerBlobFiles(root)) {
    if (file.hash !== null && keep.has(file.hash)) continue;
    await rm(file.path, { force: true });
    touched.add(dirname(file.path));
    removed += 1;
  }
  // Drop shard directories this sweep emptied; rmdir fails (and is ignored) when anything remains.
  for (const dir of touched) if (!dir.endsWith(".tmp")) await rmdir(dir).catch(() => undefined);
  return removed;
}

/** Unlink every blob under `root` not in `keep`, and every temp file. Only a missing directory counts as empty. Used by purge and the sync-time collector, which own the pinned replica directory and must leave nothing behind. */
async function unlinkBlobsIn(root: string, keep: Set<string>): Promise<number> {
  let removed = 0;
  for (const shard of await entriesOf(root)) {
    const shardPath = join(root, shard);
    if (shard === ".tmp") {
      for (const name of await entriesOf(shardPath)) {
        await rm(join(shardPath, name), { force: true });
        removed += 1;
      }
      continue;
    }
    let kept = 0;
    for (const name of await entriesOf(shardPath)) {
      if (isHash(name) && keep.has(name)) {
        kept += 1;
        continue;
      }
      await rm(join(shardPath, name), { force: true });
      removed += 1;
    }
    if (kept === 0) await rmdir(shardPath).catch(() => undefined);
  }
  return removed;
}

async function entriesOf(path: string): Promise<string[]> {
  try {
    return await readdir(path);
  } catch (error) {
    if (errnoOf(error) === "ENOENT") return [];
    throw error;
  }
}

export type SqliteGrantInstall = {
  installedAt: number;
  effectiveExpiresAt: number;
  consentDeadline: number;
  consentAnchor: ReplicaConsentAnchor;
};

export type SqliteGrantPolicy = {
  at: number;
  ttlMs: number;
  consentDeadline: number;
  consentAnchor: ReplicaConsentAnchor;
};

/** Crash- and race-test seam at SQLite durability boundaries. */
export type StoreFaults = {
  /** Blobs are durable; no row references them yet. */
  afterBlobs?(): void | Promise<void>;
  /** Rows and cursor are written inside the open transaction, not committed. */
  beforeCommit?(): void;
  /** The page is committed. */
  afterCommit?(): void;
  /** A revocation purge is committed; its blobs are not unlinked yet. */
  afterPurgeMark?(): void;
  /** Garbage collection holds an open write transaction while asynchronous blob I/O runs. */
  afterGarbageCollectionBegin?(): void | Promise<void>;
};

/**
 * Runs a mutation section (every database write and every filesystem
 * change). The CLI passes one that holds the profile lock briefly and
 * refuses when the profile was deleted, so a command never writes into or
 * recreates a deleted profile.
 */
export type MutationGuard = <T>(section: () => Promise<T>) => Promise<T>;

export type SqliteReplicaStoreOptions = {
  /** Create the replica directory and database if missing (else REPLICA_NOT_FOUND). */
  create: boolean;
  /** A checked entry's inode: reject replacement before SQLite sees its path. */
  expectedDirectory?: { dev: number; ino: number };
  sqlite?: SqliteOpener;
  /** Clock for leases and status (ms since epoch). */
  now?: () => number;
  guard?: MutationGuard;
  /** Quota admission, run inside applyPage's guarded mutation before any write (TC-858 S5). */
  admit?: ReplicaAdmitHook;
  /** Partition the store belongs to; reported to `admit`. */
  partitionId?: string;
};

/** Crash-test seam key. Only tests import it (from this module, not the package entry). */
export const FAULTS = Symbol("tinycloud.replica.faults");
type InternalOptions = SqliteReplicaStoreOptions & { [FAULTS]?: StoreFaults };

/** Stores may be abandoned without close by callers; release their directory descriptor on collection. */
const pinnedDirectories = new FinalizationRegistry<number>((fd) => {
  try { closeSync(fd); } catch { /* The process may already be shutting down. */ }
});

/** A checked SQLite handle stays pinned until the last controller for its directory closes. */
type SharedWritable = {
  key: string;
  db: SqliteDatabase;
  directoryFd: number | undefined;
  pinnedDir: string;
  namedPath: string;
  dev: number;
  ino: number;
  references: number;
  mutationTail: Promise<void>;
};

const writableStores = new Map<string, SharedWritable>();

function releaseWritable(shared: SharedWritable): void {
  if (shared.references === 0 || --shared.references !== 0) return;
  if (writableStores.get(shared.key) === shared) writableStores.delete(shared.key);
  try { shared.db.close(); } finally { if (shared.directoryFd !== undefined) closeSync(shared.directoryFd); }
}

const sharedStores = new FinalizationRegistry<SharedWritable>((shared) => {
  try { releaseWritable(shared); } catch { /* The process may already be shutting down. */ }
});

/** Serialize transactions, not pre-commit blob I/O: revocation must still fence an in-flight writer. */
async function acquireWritableMutation(shared: SharedWritable): Promise<() => void> {
  const previous = shared.mutationTail;
  let release!: () => void;
  shared.mutationTail = new Promise<void>((resolve) => { release = resolve; });
  await previous;
  return release;
}

const activeReadSection = new AsyncLocalStorage<{ controller: SqliteReplicaStore; active: boolean }>();

/**
 * The CLI replica store: SQLite (WAL, synchronous=FULL) for entries, cursor
 * and authority, committed in one transaction per page; content-addressed
 * blob files written with fsync + link before any row references them.
 */
export class SqliteReplicaStore implements ReplicaStore {
  readonly dir: string;
  readonly #database: SqliteDatabase;
  get #db(): SqliteDatabase {
    if (this.#closed) throw new ReplicaError(ReplicaErrorCode.CLOSED, "The replica store is closed.");
    return this.#database;
  }
  #closed = false;
  #closing = false;
  #closePromise?: Promise<void>;
  #activeMutations = 0;
  #drained?: () => void;
  readonly #shared?: SharedWritable;
  readonly #readonlySnapshot: boolean;
  readonly #pinnedDir: string;
  #directoryFd?: number;
  #holder: string | undefined;
  readonly #now: () => number;
  readonly #faults: StoreFaults;
  readonly #guard: MutationGuard;
  /** Identity of the database file this store opened: a deleted-and-recreated replica is a different file. */
  readonly #ino: number;
  readonly #admit: ReplicaAdmitHook | undefined;
  readonly #partitionId: string;
  readonly #dev: number;
  readonly #namedAncestors: readonly NamedPathIdentity[];

  private constructor(dir: string, db: SqliteDatabase, identity: { dev: number; ino: number }, options: SqliteReplicaStoreOptions, directoryFd?: number, namedAncestors: readonly NamedPathIdentity[] = [], shared?: SharedWritable, readonlySnapshot = false) {
    this.dir = dir;
    this.#pinnedDir = shared?.pinnedDir ?? (directoryFd !== undefined && process.platform === "linux" ? `/proc/self/fd/${directoryFd}` : dir);
    this.#directoryFd = directoryFd;
    this.#shared = shared;
    this.#readonlySnapshot = readonlySnapshot;
    if (shared) {
      shared.references++;
      sharedStores.register(this, shared, this);
    } else if (directoryFd !== undefined) {
      pinnedDirectories.register(this, directoryFd, this);
    }
    this.#database = db;
    this.#ino = identity.ino;
    this.#dev = identity.dev;
    this.#now = options.now ?? Date.now;
    this.#faults = (options as InternalOptions)[FAULTS] ?? {};
    this.#admit = options.admit;
    this.#partitionId = options.partitionId ?? "";
    this.#guard = options.guard ?? ((section) => section());
    this.#namedAncestors = namedAncestors;
  }

  /**
   * Read-only status snapshot; does not create a replica, migrate, recover
   * revocation cleanup, or enter the mutation guard. An existing database is
   * opened normally in read-only WAL mode so committed WAL state is visible.
   */

  static async inspect(
    dir: string,
    options: { now?: () => number; signal?: AbortSignal } = {},
  ): Promise<{ state: ReplicaState; status: ReplicaStatus; grantInstall: SqliteGrantInstall | null; activeGrantInstall: SqliteGrantInstall | null } | null> {
    const checkAbort = () => {
      if (options.signal?.aborted) throw options.signal.reason ?? new ReplicaError(ReplicaErrorCode.CLOSED, "Replica status inspection was cancelled.");
    };
    checkAbort();
    const dbPath = join(dir, "replica.db");
    let identity: Stats;
    try {
      identity = await lstat(dbPath);
      if (!identity.isFile()) return null;
    } catch (error) {
      if (errnoOf(error) === "ENOENT") return null;
      throw storageError(error, "Inspecting the replica");
    }
    checkAbort();
    const opener = await loadSqlite();
    checkAbort();
    let db: SqliteDatabase | undefined;
    let releaseOpen: (() => void) | undefined;
    try {
      releaseOpen = await acquireSqliteOpen();
      const checked = await openVerifiedDatabase(dbPath, opener, { readonly: true, expected: identity });
      db = checked.db;
      releaseOpen();
      releaseOpen = undefined;
      db.exec("PRAGMA busy_timeout = 0");
      checkAbort();
      const store = new SqliteReplicaStore(dir, db, checked.identity, { create: false, ...(options.now ? { now: options.now } : {}) });
      for (let attempt = 0; attempt < 2; attempt++) {
        const before = db.get<{ data_version: number }>("PRAGMA data_version")!.data_version;
        const state = await store.open();
        checkAbort();
        if (state === null) return null;
        const status = await store.status();
        const latest = state.pendingGrant ?? state.grant;
        const version = db.get<{ user_version: number }>("PRAGMA user_version")?.user_version ?? 0;
        const grantInstall = latest === null || version < 2 ? null : await store.getGrantInstall(latest.cid);
        const activeGrantInstall = state.grant === null || version < 2 ? null
          : state.grant === latest ? grantInstall : await store.getGrantInstall(state.grant.cid);
        await new Promise<void>((resolve) => setImmediate(resolve));
        checkAbort();
        const after = db.get<{ data_version: number }>("PRAGMA data_version")!.data_version;
        if (before === after) return { state, status, grantInstall, activeGrantInstall };
      }
      throw new ReplicaError(ReplicaErrorCode.BUSY, "The replica changed during status inspection.");
    } catch (error) {
      if (/SQLITE_BUSY|database is locked/i.test(error instanceof Error ? error.message : String(error))) {
        throw new ReplicaError(ReplicaErrorCode.BUSY, "The replica is busy during status inspection.", undefined, { cause: error });
      }
      throw storageError(error, "Inspecting the replica");
    } finally {
      releaseOpen?.();
      if (db) {
        const releaseClose = await acquireSqliteOpen();
        try { db.close(); } finally { releaseClose(); }
      }
    }
  }

  /**
   * Blob content bytes on disk in the replica at `dir` (0 when absent): the writer's blob files under `blobs/`,
   * including writer temp files and blobs no entry references any more, so garbage a failed sync
   * left behind still counts. Counts exactly what `collectOrphans` may delete: foreign entries
   * (stray files, symlinks, unknown names) are neither counted nor touched. Only blob content is counted: not the database, its WAL, rows or the
   * pending store. Filesystem-only: it opens no
   * database, so it can sum a profile's replicas under the caller's own mutation hold.
   */
  static async contentBytes(dir: string): Promise<number> {
    try {
      let bytes = 0;
      for (const file of await writerBlobFiles(join(dir, "blobs"))) bytes += file.size;
      return bytes;
    } catch (error) {
      throw storageError(error, "Measuring replica content");
    }
  }

  /**
   * Remove blobs and temp files in the replica at `dir` that no committed row references: what a
   * crash between writing blobs and committing (or between committing and collecting) leaves.
   * Returns the number of files removed; 0 when the replica is absent or unreadable.
   *
   * The caller MUST hold the profile mutation guard, which every writer of this replica holds
   * across its blob write and commit; that is what makes an unreferenced blob safe to delete
   * (it cannot belong to an in-flight write). Never call it without that hold. The database is
   * read only, so nothing here can take a lease or change committed state.
   */
  static async collectOrphans(dir: string): Promise<number> {
    const dbPath = join(dir, "replica.db");
    const identity = await lstat(dbPath).catch(() => undefined);
    if (!identity?.isFile()) return 0;
    const opener = await loadSqlite();
    let keep: Set<string>;
    let db: SqliteDatabase | undefined;
    try {
      db = opener(dbPath, { readonly: true });
      db.exec("PRAGMA busy_timeout = 0");
      keep = new Set(db.all<{ hash: string }>("SELECT DISTINCT hash FROM entry WHERE content = 1").map((row) => row.hash));
    } catch {
      return 0; // locked or unreadable: skip, never delete under contention
    } finally {
      db?.close();
    }
    try {
      return await unlinkWriterOrphans(join(dir, "blobs"), keep);
    } catch (error) {
      throw storageError(error, "Collecting orphaned content");
    }
  }

  /**
   * Open the replica store in `dir`. With `create: false` a missing replica is
   * REPLICA_NOT_FOUND and nothing is written to disk.
   */
  static async open(dir: string, options: SqliteReplicaStoreOptions): Promise<SqliteReplicaStore> {
    const namedDbPath = join(dir, "replica.db");
    if (!options.create) {
      const exists = await lstat(namedDbPath).then(
        (stats) => stats.isFile(),
        () => false,
      );
      if (!exists) throw new ReplicaError(ReplicaErrorCode.NOT_FOUND, `No regular replica database at ${dir}.`);
    }
    const releaseOpen = await acquireSqliteOpen();
    let store: SqliteReplicaStore | undefined;
    let directoryFd: number | undefined;
    try {
      if (options.create) await mkdir(dir, { recursive: true, mode: 0o700 });
      if (process.platform === "linux") {
        directoryFd = openSync(dir, fsConstants.O_RDONLY | fsConstants.O_DIRECTORY | fsConstants.O_NOFOLLOW);
      }
      const opened = directoryFd === undefined ? lstatSync(dir, { bigint: true }) : fstatSync(directoryFd, { bigint: true });
      if (!opened.isDirectory() || opened.isSymbolicLink() ||
          (options.expectedDirectory &&
            (opened.dev !== BigInt(options.expectedDirectory.dev) || opened.ino !== BigInt(options.expectedDirectory.ino)))) {
        throw new Error("The replica directory changed before SQLite opened it.");
      }
      const namedAncestors = process.platform === "linux" ? [] : await captureNamedPath(dir);
      if (namedAncestors.length &&
          (namedAncestors[namedAncestors.length - 1]!.dev !== opened.dev || namedAncestors[namedAncestors.length - 1]!.ino !== opened.ino)) {
        throw new Error("The replica directory changed while checking its ancestry.");
      }
      const pinnedDir = directoryFd === undefined ? dir : `/proc/self/fd/${directoryFd}`;
      const dbPath = join(pinnedDir, "replica.db");
      if (options.create) {
        await mkdir(join(pinnedDir, "blobs", ".tmp"), { recursive: true, mode: 0o700 });
        await Promise.all([chmod(pinnedDir, 0o700), chmod(join(pinnedDir, "blobs"), 0o700), chmod(join(pinnedDir, "blobs", ".tmp"), 0o700)]);
        // SQLite gives -wal and -shm the database file's mode.
        // Only the winner creates/chmods the file; concurrent openers use the existing leaf.
        const handle = await open(dbPath, fsConstants.O_CREAT | fsConstants.O_EXCL | fsConstants.O_RDWR | fsConstants.O_NOFOLLOW, 0o600).catch((error: unknown) => {
          if (errnoOf(error) === "EEXIST") return null;
          throw error;
        });
        if (handle) {
          try { await handle.chmod(0o600); } finally { await handle.close(); }
        }
      }
      const leaf = await open(dbPath, fsConstants.O_RDONLY | fsConstants.O_NOFOLLOW);
      let db: SqliteDatabase | undefined;
      try {
        const identity = await leaf.stat();
        const named = await lstat(dbPath);
        if (!identity.isFile() || !named.isFile() || named.dev !== identity.dev || named.ino !== identity.ino) {
          throw new Error("The replica database changed before SQLite opened it.");
        }
        const key = `${opened.dev}:${opened.ino}`;
        const active = writableStores.get(key);
        if (active && (active.dev !== identity.dev || active.ino !== identity.ino)) {
          throw new Error("The replica database changed while another controller holds it open.");
        }
        if (active && !options.sqlite) {
          const namedDirectory = lstatSync(dir, { bigint: true });
          if (!namedDirectory.isDirectory() || namedDirectory.dev !== opened.dev || namedDirectory.ino !== opened.ino) {
            throw new Error("The replica directory changed before its checked SQLite handle could be shared.");
          }
          const pinned = active.directoryFd === undefined
            ? lstatSync(active.pinnedDir, { bigint: true })
            : fstatSync(active.directoryFd, { bigint: true });
          const activeLeaf = lstatSync(join(active.pinnedDir, "replica.db"));
          if (!pinned.isDirectory() || pinned.dev !== opened.dev || pinned.ino !== opened.ino ||
              !activeLeaf.isFile() || activeLeaf.dev !== identity.dev || activeLeaf.ino !== identity.ino ||
              (active.directoryFd === undefined && active.namedPath !== dir)) {
            throw new Error("The live replica changed before its checked SQLite handle could be shared.");
          }
          if (directoryFd !== undefined) {
            closeSync(directoryFd);
            directoryFd = undefined;
          }
          store = new SqliteReplicaStore(dir, active.db, identity, options, active.directoryFd, namedAncestors, active);
        }
        if (!store) {
          const opener = options.sqlite ?? (await loadSqlite());
          const previousFds = process.platform === "linux" && !options.sqlite
            ? new Map(readdirSync("/proc/self/fd").map((fd) => {
              try { return [fd, readlinkSync(`/proc/self/fd/${fd}`)] as const; } catch { return [fd, ""] as const; }
            }))
            : null;
          db = opener(dbPath);
          const afterOpen = lstatSync(dbPath);
          if (!afterOpen.isFile() || afterOpen.dev !== identity.dev || afterOpen.ino !== identity.ino) {
            throw new Error("The replica database changed while SQLite opened it.");
          }
          // Bun opens the file lazily on its first read. Verify that descriptor before any mutating PRAGMA.
          // SQLite may resolve WAL/SHM sidecars by the database's named path;
          // the pinned directory does not make a concurrent external rename atomic.
          if (previousFds) db.get("SELECT count(*) FROM sqlite_master");
          if (previousFds) {
            const databases = readdirSync("/proc/self/fd").filter((fd) => {
              try {
                const target = readlinkSync(`/proc/self/fd/${fd}`);
                return target.endsWith("/replica.db") && previousFds.get(fd) !== target;
              } catch { return false; }
            });
            if (databases.length === 0 || databases.some((fd) => {
              try {
                const actual = fstatSync(Number(fd));
                return actual.dev !== identity.dev || actual.ino !== identity.ino;
              } catch { return true; }
            })) {
              throw new Error("SQLite opened a different replica database.");
            }
          }
          const after = lstatSync(dbPath);
          if (!after.isFile() || after.dev !== identity.dev || after.ino !== identity.ino) {
            throw new Error("The replica database changed while SQLite opened it.");
          }
          db.exec("PRAGMA busy_timeout = 5000");
          db.exec("PRAGMA journal_mode = WAL");
          db.exec("PRAGMA synchronous = FULL");
          db.exec("PRAGMA secure_delete = ON");
          db.exec("PRAGMA foreign_keys = ON");
          const version = db.get<{ user_version: number }>("PRAGMA user_version")?.user_version ?? 0;
          if (version > SCHEMA_VERSION) {
            throw new ReplicaError(
              ReplicaErrorCode.STORAGE_ERROR,
              `The replica at ${dir} was written by a newer tc (schema ${version}); upgrade tc to read it.`,
            );
          }
          if (version < SCHEMA_VERSION) {
            db.exec("BEGIN IMMEDIATE");
            db.exec(SCHEMA);
            db.exec(`PRAGMA user_version = ${SCHEMA_VERSION}`);
            db.exec("COMMIT");
          }
          const shared: SharedWritable = {
            key, db, directoryFd, pinnedDir, namedPath: dir, dev: identity.dev, ino: identity.ino,
            references: 0, mutationTail: Promise.resolve(),
          };
          store = new SqliteReplicaStore(dir, db, identity, options, directoryFd, namedAncestors, shared);
          if (!options.sqlite) writableStores.set(key, shared);
          db = undefined;
        }
      } finally {
        try { db?.close(); } finally { await leaf.close(); }
      }
    } catch (error) {
      if (store) await store.close().catch(() => undefined);
      else if (directoryFd !== undefined) closeSync(directoryFd);
      throw storageError(error, `Opening the replica at ${dir}`);
    } finally {
      releaseOpen();
    }
    // A revocation purge interrupted by a crash (or by a writer that put
    // content back after it) finishes on the next open.
    try {
      const row = store.#row();
      if (row?.revoked_detail != null && (row.purge_pending === 1 || (await store.#holdsContentFiles().catch(() => true)))) {
        await store.#finishRevocationPurge().catch(() => undefined);
      }
      return store;
    } catch (error) {
      await store.close().catch(() => undefined);
      throw error;
    }
  }


  /**
   * A gated read borrows this controller's already-verified writable handle.
   * Borrow before the first await: the parent may close in the callback, but
   * its pin and native handle remain live until the snapshot releases them.
   * Serialize BEGIN through COMMIT/ROLLBACK with writes on the shared handle.
   */
  async readTransaction<T>(
    generation: number,
    checkGate: () => Promise<void>,
    section: (store: SqliteReplicaStore) => Promise<T>,
  ): Promise<T> {
    this.#assertAccepting();
    const shared = this.#shared;
    if (!shared) throw new ReplicaError(ReplicaErrorCode.CLOSED, "The replica handle is closed.");
    const snapshot = new SqliteReplicaStore(
      this.dir, shared.db, { dev: this.#dev, ino: this.#ino },
      { create: false, now: this.#now }, shared.directoryFd, this.#namedAncestors, shared, true,
    );
    let release: (() => void) | undefined;
    let active = false;
    let callbackFailed = false;
    try {
      release = await acquireWritableMutation(shared);
      await snapshot.#assertReadIdentity();
      snapshot.#db.exec("BEGIN");
      active = true;
      const tombstone = snapshot.#db.get<{ generation: number }>("SELECT generation FROM replica WHERE id = 1");
      try { await checkGate(); } catch (error) { callbackFailed = true; throw error; }
      if (tombstone === undefined || tombstone.generation !== generation) {
        throw new ReplicaError(ReplicaErrorCode.RESET_REQUIRED, "The replica generation changed; reopen it to continue.");
      }
      let result: T;
      const context = { controller: this, active: true };
      try {
        try { result = await activeReadSection.run(context, () => section(snapshot)); }
        catch (error) { callbackFailed = true; throw error; }
      } finally {
        context.active = false;
      }
      try { await checkGate(); } catch (error) { callbackFailed = true; throw error; }
      await snapshot.#assertReadIdentity();
      snapshot.#db.exec("COMMIT");
      active = false;
      return result;
    } catch (error) {
      if (callbackFailed) throw error;
      if (isReplicaError(error) || (typeof error === "object" && error !== null && "code" in error &&
          error.code === "REPLICA_GATED")) throw error;
      if (["ENOENT", "ELOOP", "ENOTDIR"].includes(String(errnoOf(error))) ||
          /replica database changed|SQLite opened a different replica database/i.test(error instanceof Error ? error.message : String(error))) {
        throw new ReplicaError(ReplicaErrorCode.RESET_REQUIRED, "The replica was replaced; reopen it to continue.", undefined, { cause: error });
      }
      throw storageError(error, "Reading the replica snapshot");
    } finally {
      if (active) {
        try { snapshot.#db.exec("ROLLBACK"); } catch { /* Preserve the original error. */ }
      }
      try { await snapshot.close(); } finally { release?.(); }
    }
  }

  async #assertReadIdentity(): Promise<void> {
    const shared = this.#shared!;
    const pinned = shared.directoryFd === undefined ? lstatSync(shared.pinnedDir) : fstatSync(shared.directoryFd);
    const namedDir = lstatSync(this.dir);
    const namedDb = lstatSync(join(this.dir, "replica.db"));
    const pinnedDb = lstatSync(join(shared.pinnedDir, "replica.db"));
    if (!pinned.isDirectory() || !namedDir.isDirectory() ||
        pinned.dev !== namedDir.dev || pinned.ino !== namedDir.ino ||
        !namedDb.isFile() || !pinnedDb.isFile() ||
        namedDb.dev !== this.#dev || namedDb.ino !== this.#ino ||
        pinnedDb.dev !== this.#dev || pinnedDb.ino !== this.#ino) {
      throw new ReplicaError(ReplicaErrorCode.RESET_REQUIRED, "The replica was replaced during its read; reopen it to continue.");
    }
    if (this.#namedAncestors.length) {
      const ancestors = await captureNamedPath(this.dir);
      if (ancestors.length !== this.#namedAncestors.length ||
          ancestors.some((entry, index) => entry.dev !== this.#namedAncestors[index]!.dev || entry.ino !== this.#namedAncestors[index]!.ino)) {
        throw new ReplicaError(ReplicaErrorCode.RESET_REQUIRED, "The replica directory was replaced; reopen it to continue.");
      }
    }
  }

  #row(): ReplicaRow | undefined {
    return this.#db.get<ReplicaRow>("SELECT * FROM replica WHERE id = 1");
  }

  /** Refuse to touch the filesystem for a replica that was deleted (or replaced) under us. */
  async #assertPresent(): Promise<void> {
    const identity = await lstat(join(this.#pinnedDir, "replica.db")).catch(() => null);
    if (!identity?.isFile() || identity.dev !== this.#dev || identity.ino !== this.#ino) {
      throw new ReplicaError(
        ReplicaErrorCode.NOT_FOUND,
        `The replica at ${this.dir} was deleted while this command ran (its profile was deleted or the replica purged); nothing more was written.`,
      );
    }
  }

  /** New calls stop at close; accepted mutation sections may still finish their transactions. */
  #assertAccepting(): void {
    if (this.#closing || this.#closed) {
      throw new ReplicaError(ReplicaErrorCode.CLOSED, "The replica store is closed.");
    }
  }

  /** A short mutation section: guarded (profile lock) and checked against the database this store opened. */
  #mutate<T>(section: () => Promise<T>): Promise<T> {
    this.#assertAccepting();
    if (this.#readonlySnapshot) {
      throw new ReplicaError(ReplicaErrorCode.STORAGE_ERROR, "A read-only replica snapshot cannot mutate the shared database.");
    }
    const read = activeReadSection.getStore();
    if (read?.active && read.controller === this) {
      throw new ReplicaError(
        ReplicaErrorCode.STORAGE_ERROR,
        "mutation attempted on the same controller while its readTransaction section is active; this would deadlock",
      );
    }
    this.#activeMutations++;
    return (async () => {
      try {
        return await this.#guard(async () => {
          await this.#assertPresent();
          return section();
        });
      } finally {
        if (--this.#activeMutations === 0) {
          const drained = this.#drained;
          this.#drained = undefined;
          drained?.();
        }
      }
    })();
  }

  /** Run `body` in a write transaction (BEGIN IMMEDIATE). Callers outside a mutation section use `#guardedWrite`. */
  async #write<T>(action: string, body: () => T): Promise<T> {
    const release = this.#shared ? await acquireWritableMutation(this.#shared) : undefined;
    try {
      try {
        this.#db.exec("BEGIN IMMEDIATE");
      } catch (error) {
        throw storageError(error, action);
      }
      try {
        const result = body();
        this.#db.exec("COMMIT");
        return result;
      } catch (error) {
        try {
          this.#db.exec("ROLLBACK");
        } catch {
          // The transaction is already gone.
        }
        throw storageError(error, action);
      }
    } finally {
      release?.();
    }
  }

  /** One write transaction as its own mutation section. */
  #guardedWrite<T>(action: string, body: () => T): Promise<T> {
    return this.#mutate(async () => this.#write(action, body));
  }

  /**
   * The caller still holds a live lease (its token, not expired), and the
   * replica is not revoked (unless `allowRevoked`). Inside a write
   * transaction this fences the write; before one it refuses early.
   */
  #checkLease(t: LeaseToken, options: { allowRevoked?: boolean } = {}): void {
    const row = this.#db.get<{ lease_token: number; lease_holder: string | null; lease_expires_at: number | null; revoked_detail: string | null }>(
      "SELECT lease_token, lease_holder, lease_expires_at, revoked_detail FROM replica WHERE id = 1",
    );
    if (row?.revoked_detail != null && options.allowRevoked !== true) {
      throw new ReplicaError(ReplicaErrorCode.GRANT_REVOKED, `The replica's grant was revoked: ${row.revoked_detail}`);
    }
    if (row === undefined || row.lease_token !== t.token || row.lease_holder !== t.holder) {
      throw new ReplicaError(ReplicaErrorCode.BUSY, "Another process took over this replica's sync lease.");
    }
    if (row.lease_expires_at === null || row.lease_expires_at <= this.#now()) {
      throw new ReplicaError(ReplicaErrorCode.BUSY, "This process's sync lease expired; nothing was written.");
    }
  }

  async open(): Promise<ReplicaState | null> {
    this.#assertAccepting();
    let row: ReplicaRow | undefined;
    try {
      row = this.#row();
    } catch (error) {
      throw storageError(error, "Reading the replica");
    }
    if (row === undefined) return null;
    assertFolderPrefix(row.prefix);
    return {
      config: {
        name: row.name,
        replicaId: row.replica_id,
        host: row.host,
        space: row.space,
        prefix: row.prefix,
        deviceDid: row.device_did,
        allowSecrets: row.allow_secrets === 1,
        localReadPolicy: row.local_read_policy,
        retentionGrantCid: row.retention_grant_cid,
      },
      grant: grantOf(row.grant_cid, row.grant_bytes, row.grant_audience, row.grant_issuer, row.grant_nbf, row.grant_exp),
      pendingGrant: grantOf(
        row.pending_grant_cid,
        row.pending_grant_bytes,
        row.pending_grant_audience,
        row.pending_grant_issuer,
        row.pending_grant_nbf,
        row.pending_grant_exp,
      ),
      nodeDid: row.node_did,
      authority: row.attested === 1 ? { notBefore: row.not_before, expiresAt: row.expires_at, retainUntil: row.retain_until } : null,
      revoked: row.revoked_detail,
      retentionRevoked: row.retention_revoked,
      pendingGrantError: row.pending_grant_error === null ? null : (JSON.parse(row.pending_grant_error) as ReplicaLastError),
      cursor: row.cursor,
      coverage: row.coverage,
      generation: row.generation,
      createdAt: row.created_at,
      lastSyncAt: row.last_sync_at,
      lastCompleteAt: row.last_complete_at,
      lastError: row.last_error === null ? null : (JSON.parse(row.last_error) as ReplicaLastError),
      lastReset: row.last_reset === null ? null : (JSON.parse(row.last_reset) as { at: string; reason: string }),
    };
  }

  async init(c: ReplicaConfig): Promise<void> {
    assertFolderPrefix(c.prefix);
    await this.#guardedWrite("Creating the replica", () => {
      if (this.#row() !== undefined) {
        throw new ReplicaError(ReplicaErrorCode.CONFIG_MISMATCH, `Replica ${c.name} already exists.`);
      }
      this.#db.run(
        `INSERT INTO replica (id, name, replica_id, host, space, prefix, device_did, allow_secrets, local_read_policy,
           retention_grant_cid, coverage, created_at)
         VALUES (1, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'empty', ?)`,
        c.name,
        c.replicaId,
        c.host,
        c.space,
        c.prefix,
        c.deviceDid,
        c.allowSecrets ? 1 : 0,
        c.localReadPolicy,
        c.retentionGrantCid,
        new Date(this.#now()).toISOString(),
      );
    });
  }

  /** Update the retention opt-in; it takes effect at the next sync. */
  async setRetentionGrant(cid: string | null): Promise<void> {
    await this.#guardedWrite("Updating the retention grant", () => {
      // Changing the CID invalidates the attested retainUntil: it was earned
      // under the previous retain grant, so only a fresh sync under the new
      // CID may re-establish it.
      this.#db.run(
        "UPDATE replica SET retention_grant_cid = ?, local_read_policy = ?, retain_until = NULL WHERE id = 1 AND retention_grant_cid IS NOT ?",
        cid,
        cid === null ? "whileGrantValid" : "retainAfterExpiry",
        cid,
      );
    });
  }

  /** Per-CID first-install anchor and policy bound share the pending-grant transaction. */
  #grantInstall(cid: string): SqliteGrantInstall | null {
    const row = this.#db.get<{
      installed_at: number;
      effective_expires_at: number;
      consent_deadline: number;
      consent_anchor_at: number;
      consent_anchor_source: string;
    }>(
      "SELECT installed_at, effective_expires_at, consent_deadline, consent_anchor_at, consent_anchor_source FROM grant_install WHERE cid = ?",
      cid,
    );
    if (row === undefined) return null;
    if (!(row.consent_anchor_source === "siwe" || row.consent_anchor_source === "delegation_iat" ||
          row.consent_anchor_source === "delegation_nbf" || row.consent_anchor_source === "first_install") ||
        !Number.isSafeInteger(row.installed_at) || row.installed_at < 0 ||
        !Number.isSafeInteger(row.effective_expires_at) || row.effective_expires_at < 0 ||
        !Number.isSafeInteger(row.consent_deadline) || row.consent_deadline < 0 ||
        !Number.isSafeInteger(row.consent_anchor_at) || row.consent_anchor_at < 0) {
      throw new ReplicaError(ReplicaErrorCode.GRANT_EXPIRED, "The stored grant expiry or consent anchor is invalid.");
    }
    return {
      installedAt: row.installed_at,
      effectiveExpiresAt: row.effective_expires_at,
      consentDeadline: row.consent_deadline,
      consentAnchor: { at: row.consent_anchor_at, source: row.consent_anchor_source },
    };
  }

  async getGrantInstall(cid: string): Promise<SqliteGrantInstall | null> {
    return this.#grantInstall(cid);
  }

  /** Every installed CID, including superseded ones, for an origin-wide purge floor. */
  async grantInstallTimes(): Promise<Array<{ cid: string; installedAt: number }>> {
    const rows = this.#db.all<{ cid: string; installed_at: number }>(
      "SELECT cid, installed_at FROM grant_install",
    );
    return rows.map((row) => {
      if (typeof row.cid !== "string" || row.cid.length === 0 ||
          !Number.isSafeInteger(row.installed_at) || row.installed_at < 0) {
        throw new ReplicaError(ReplicaErrorCode.GRANT_EXPIRED, "The stored grant install time is invalid.");
      }
      return { cid: row.cid, installedAt: row.installed_at };
    });
  }

  /** Phase 2 installed grants cannot commit a page after their shorter local TTL. */
  #assertInstalledGrantTime(): void {
    const row = this.#row();
    const cid = row?.pending_grant_cid ?? row?.grant_cid;
    if (cid === undefined || cid === null) return;
    const installed = this.#grantInstall(cid);
    // Standalone Phase 1 stores have no grant policy; the Node adapter
    // separately refuses a missing install record before starting sync.
    const now = this.#now();
    if (installed !== null && (now >= installed.effectiveExpiresAt ||
        now >= installed.consentDeadline)) {
      throw new ReplicaError(ReplicaErrorCode.GRANT_EXPIRED, "The installed grant expired before this page committed.");
    }
  }

  #storeGrantPolicy(g: GrantRecord, policy: SqliteGrantPolicy, existing: SqliteGrantInstall | null): SqliteGrantInstall {
    const installedAt = existing?.installedAt ?? policy.at;
    // A recompute may lower the stored consent deadline, never raise it (CONTRACT §3).
    const keepExisting = existing !== null && existing.consentDeadline < policy.consentDeadline;
    const consentDeadline = keepExisting ? existing.consentDeadline : policy.consentDeadline;
    const consentAnchor = keepExisting ? existing.consentAnchor : policy.consentAnchor;
    const effectiveExpiresAt = Math.min(
      g.expiresAt === null ? Infinity : g.expiresAt * 1000,
      installedAt + policy.ttlMs,
      consentDeadline,
    );
    if (!Number.isSafeInteger(installedAt) || installedAt < 0 ||
        !Number.isSafeInteger(effectiveExpiresAt) || effectiveExpiresAt < 0 ||
        !Number.isSafeInteger(consentDeadline) || consentDeadline < 0 ||
        !Number.isSafeInteger(consentAnchor.at) || consentAnchor.at < 0 ||
        !Number.isSafeInteger(policy.ttlMs) || policy.ttlMs <= 0) {
      throw new ReplicaError(ReplicaErrorCode.GRANT_EXPIRED, "The replica grant has no finite effective expiry.");
    }
    this.#db.run(
      `INSERT INTO grant_install (cid, installed_at, effective_expires_at, consent_deadline, consent_anchor_at, consent_anchor_source)
       VALUES (?, ?, ?, ?, ?, ?)
       ON CONFLICT (cid) DO UPDATE SET effective_expires_at = excluded.effective_expires_at,
         consent_deadline = excluded.consent_deadline, consent_anchor_at = excluded.consent_anchor_at,
         consent_anchor_source = excluded.consent_anchor_source`,
      g.cid, installedAt, effectiveExpiresAt, consentDeadline,
      consentAnchor.at, consentAnchor.source,
    );
    return { installedAt, effectiveExpiresAt, consentDeadline, consentAnchor };
  }

  async installGatedGrant(g: GrantRecord, policy: SqliteGrantPolicy): Promise<SqliteGrantInstall> {
    return this.#guardedWrite("Installing the gated grant", () => {
      const row = this.#row();
      if (row === undefined) throw new ReplicaError(ReplicaErrorCode.NOT_FOUND, "The replica has not been created.");
      const previous = this.#grantInstall(g.cid);
      if (previous === null && (row.grant_cid === g.cid || row.pending_grant_cid === g.cid)) {
        throw new ReplicaError(ReplicaErrorCode.GRANT_EXPIRED, "The installed grant has no durable first-install time.");
      }
      const next = this.#storeGrantPolicy(g, policy, previous);
      if (next.effectiveExpiresAt <= this.#now()) {
        throw new ReplicaError(ReplicaErrorCode.GRANT_EXPIRED, "The replica grant expired under the current policy.");
      }
      if (row.grant_cid !== g.cid && row.pending_grant_cid !== g.cid) {
        this.#db.run(
          `UPDATE replica SET pending_grant_cid = ?, pending_grant_bytes = ?, pending_grant_audience = ?,
             pending_grant_issuer = ?, pending_grant_nbf = ?, pending_grant_exp = ?, pending_grant_error = NULL WHERE id = 1`,
          g.cid, g.bytes, g.audience, g.issuer, g.notBefore, g.expiresAt,
        );
      }
      return next;
    });
  }

  async recomputeGrantInstall(g: GrantRecord, policy: SqliteGrantPolicy): Promise<SqliteGrantInstall | null> {
    return this.#guardedWrite("Recomputing the gated grant", () => {
      const previous = this.#grantInstall(g.cid);
      return previous === null ? null : this.#storeGrantPolicy(g, policy, previous);
    });
  }

  async installGrant(g: GrantRecord): Promise<void> {
    await this.#guardedWrite("Installing the grant", () => {
      const row = this.#row();
      if (row === undefined) throw new ReplicaError(ReplicaErrorCode.NOT_FOUND, "The replica has not been created.");
      if (row.grant_cid === g.cid || row.pending_grant_cid === g.cid) return;
      this.#db.run(
        `UPDATE replica SET pending_grant_cid = ?, pending_grant_bytes = ?, pending_grant_audience = ?,
           pending_grant_issuer = ?, pending_grant_nbf = ?, pending_grant_exp = ?, pending_grant_error = NULL WHERE id = 1`,
        g.cid,
        g.bytes,
        g.audience,
        g.issuer,
        g.notBefore,
        g.expiresAt,
      );
    });
  }

  async discardPendingGrant(cid: string, detail: string): Promise<void> {
    await this.#guardedWrite("Discarding the revoked pending grant", () => {
      this.#db.run(
        `UPDATE replica SET pending_grant_cid = NULL, pending_grant_bytes = NULL, pending_grant_audience = NULL,
           pending_grant_issuer = NULL, pending_grant_nbf = NULL, pending_grant_exp = NULL, pending_grant_error = NULL,
           last_error = ? WHERE id = 1 AND pending_grant_cid = ?`,
        JSON.stringify({
          at: new Date(this.#now()).toISOString(),
          code: ReplicaErrorCode.GRANT_REVOKED,
          message: `The pending grant ${cid} was revoked and discarded: ${detail}`,
        }),
        cid,
      );
    });
  }

  async recordPendingGrantError(cid: string, e: ReplicaLastError): Promise<void> {
    await this.#guardedWrite("Recording the pending grant's refusal", () => {
      this.#db.run("UPDATE replica SET pending_grant_error = ? WHERE id = 1 AND pending_grant_cid = ?", JSON.stringify(e), cid);
    });
  }

  async markRetentionRevoked(cid: string, detail: string): Promise<void> {
    await this.#guardedWrite("Recording the retention grant's revocation", () => {
      this.#db.run(
        `UPDATE replica SET retention_grant_cid = NULL, local_read_policy = 'whileGrantValid', retain_until = NULL,
           retention_revoked = ? WHERE id = 1 AND retention_grant_cid = ?`,
        detail,
        cid,
      );
      this.#db.run(
        "UPDATE replica SET last_error = ? WHERE id = 1",
        JSON.stringify({ at: new Date(this.#now()).toISOString(), code: ReplicaErrorCode.RETENTION_GRANT_REFUSED, message: detail }),
      );
    });
  }

  async acquireSyncLease(ttlMs: number): Promise<LeaseToken | null> {
    return this.#guardedWrite("Taking the sync lease", () => {
      const row = this.#row();
      if (row === undefined) throw new ReplicaError(ReplicaErrorCode.NOT_FOUND, "The replica has not been created.");
      const now = this.#now();
      if (row.lease_holder !== null && row.lease_expires_at !== null && row.lease_expires_at > now) return null;
      const token = row.lease_token + 1;
      const holder = this.#holder ??= `${process.pid}-${randomBytes(6).toString("hex")}`;
      this.#db.run(
        "UPDATE replica SET lease_token = ?, lease_holder = ?, lease_expires_at = ? WHERE id = 1",
        token,
        holder,
        now + ttlMs,
      );
      return { token, holder };
    });
  }

  async renewLease(t: LeaseToken, ttlMs: number): Promise<void> {
    await this.#guardedWrite("Renewing the sync lease", () => {
      this.#checkLease(t);
      this.#db.run("UPDATE replica SET lease_expires_at = ? WHERE id = 1", this.#now() + ttlMs);
    });
  }

  async releaseLease(t: LeaseToken): Promise<void> {
    await this.#guardedWrite("Releasing the sync lease", () => {
      this.#db.run(
        "UPDATE replica SET lease_holder = NULL, lease_expires_at = NULL WHERE id = 1 AND lease_token = ? AND lease_holder = ?",
        t.token,
        t.holder,
      );
    });
  }

  async hasContent(hashes: string[]): Promise<Set<string>> {
    this.#assertAccepting();
    const held = new Set<string>();
    for (let start = 0; start < hashes.length; start += 500) {
      const chunk = hashes.slice(start, start + 500);
      const rows = this.#db.all<{ hash: string }>(
        `SELECT DISTINCT hash FROM entry WHERE content = 1 AND hash IN (${chunk.map(() => "?").join(",")})`,
        ...chunk,
      );
      for (const row of rows) held.add(row.hash);
    }
    return held;
  }

  #blobPath(hash: string): string {
    return join(this.#pinnedDir, "blobs", hash.slice(0, 2), hash);
  }

  /**
   * Make every blob durable before any row references it: write to a fresh
   * temp file (O_EXCL, 0600), fsync, link to its content address (an existing
   * blob wins), unlink the temp, then fsync each touched directory once.
   * Never creates the replica's own directories: a deleted replica fails.
   */
  async #writeBlobs(blobs: Map<string, Uint8Array>): Promise<void> {
    const dirs = new Set<string>();
    for (const [hash, bytes] of blobs) {
      const final = this.#blobPath(hash);
      const exists = await stat(final).then(
        () => true,
        () => false,
      );
      if (exists) continue;
      const shard = join(this.#pinnedDir, "blobs", hash.slice(0, 2));
      await mkdir(shard, { mode: 0o700 }).catch((error: unknown) => {
        if (errnoOf(error) !== "EEXIST") throw error;
      });
      const temp = join(this.#pinnedDir, "blobs", ".tmp", `${hash}.${randomBytes(6).toString("hex")}`);
      const handle = await open(temp, fsConstants.O_CREAT | fsConstants.O_EXCL | fsConstants.O_WRONLY, 0o600);
      try {
        await handle.writeFile(bytes);
        await handle.sync();
      } finally {
        await handle.close();
      }
      try {
        await link(temp, final);
      } catch (error) {
        if (errnoOf(error) !== "EEXIST") throw error;
      } finally {
        await unlink(temp);
      }
      dirs.add(shard);
      dirs.add(join(this.#pinnedDir, "blobs"));
    }
    for (const dir of dirs) {
      const handle = await open(dir, fsConstants.O_RDONLY);
      try {
        await handle.sync();
      } finally {
        await handle.close();
      }
    }
  }

  async applyPage(t: LeaseToken, p: VerifiedPage): Promise<void> {
    await this.#mutate(async () => {
      // Fence before any content reaches the disk: a writer whose lease was
      // taken over, expired or revoked writes nothing.
      this.#checkLease(t);
      this.#assertInstalledGrantTime();
      // Resolve every reused blob's size before any row changes: an earlier
      // row of this page may drop the last entry that references it.
      const reused = new Map<string, number>();
      for (const change of p.changes) {
        if (change.deleted || !change.content || p.blobs.has(change.hash) || reused.has(change.hash)) continue;
        const size = this.#db.get<{ size: number | null }>(
          "SELECT size FROM entry WHERE hash = ? AND content = 1 AND size IS NOT NULL LIMIT 1",
          change.hash,
        )?.size;
        if (size === undefined || size === null) {
          throw new ReplicaError(ReplicaErrorCode.STORAGE_ERROR, `No stored content backs ${JSON.stringify(change.key)}.`);
        }
        reused.set(change.hash, size);
      }
      // Quota admission (TC-858 S5). Runs under the same guard as the write, before any blob
      // or row changes; a refusal leaves the replica untouched. Orphaned blobs (a failed sync,
      // a crash after commit) are collected first so they are neither counted as free nor
      // charged to this replica twice; the page is then charged its NET bytes (may be negative):
      // new blobs not already stored, minus blobs only the entries this page replaces or deletes
      // reference. The budget bounds COMMITTED blob content. The replaced blobs are unlinked only
      // after the commit succeeds (never before: a failed commit must not lose data), so during
      // one page on-disk blob bytes can transiently reach cap + the bytes that page replaces.
      if (this.#admit) {
        await this.#collectLocked(t);
        const changed = new Set(p.changes.map((change) => change.key));
        const kept = new Set<string>();
        for (const change of p.changes) if (!change.deleted && change.content) kept.add(change.hash);
        let blobBytes = 0;
        for (const [hash, bytes] of p.blobs) {
          const stored = this.#db.get<{ hit: number }>(
            "SELECT 1 AS hit FROM entry WHERE hash = ? AND content = 1 AND deleted = 0 LIMIT 1",
            hash,
          );
          if (stored === undefined) blobBytes += bytes.byteLength;
        }
        const released = new Map<string, number>();
        for (const key of changed) {
          const old = this.#db.get<{ hash: string; size: number }>(
            "SELECT hash, size FROM entry WHERE key = ? AND deleted = 0 AND content = 1 AND hash IS NOT NULL AND size IS NOT NULL",
            key,
          );
          if (old === undefined || kept.has(old.hash) || released.has(old.hash)) continue;
          const holders = this.#db.all<{ key: string }>(
            "SELECT key FROM entry WHERE hash = ? AND content = 1 AND deleted = 0",
            old.hash,
          );
          if (holders.every((holder) => changed.has(holder.key))) released.set(old.hash, old.size);
        }
        let freed = 0;
        for (const size of released.values()) freed += size;
        await this.#admit({
          partitionId: this.#partitionId,
          blobBytes: blobBytes - freed,
          entries: p.changes.length,
          freeBytes: null,
        });
      }
      try {
        await this.#writeBlobs(p.blobs);
      } catch (error) {
        throw storageError(error, "Writing replica content");
      }
      await this.#faults.afterBlobs?.();
      try {
        await this.#write("Committing a sync page", () => {
          this.#checkLease(t);
          this.#assertInstalledGrantTime();
          // Authority is judged now, at the commit, not when the page arrived.
          const now = this.#now();
          if (p.window.notBefore !== null && now < Date.parse(p.window.notBefore)) {
            throw new ReplicaError(ReplicaErrorCode.GRANT_NOT_YET_VALID, `The grant is not valid before ${p.window.notBefore}; nothing was committed.`);
          }
          if (p.window.expiresAt !== null && now >= Date.parse(p.window.expiresAt)) {
            throw new ReplicaError(ReplicaErrorCode.GRANT_EXPIRED, `The grant expired at ${p.window.expiresAt}; nothing was committed.`);
          }
          for (const change of p.changes) {
            if (change.deleted) {
              this.#db.run(
                `INSERT INTO entry (key, deleted, etag, hash, metadata, content, size) VALUES (?, 1, NULL, NULL, '{}', 0, NULL)
                 ON CONFLICT (key) DO UPDATE SET deleted = 1, etag = NULL, hash = NULL, metadata = '{}', content = 0, size = NULL`,
                change.key,
              );
              continue;
            }
            const size = change.content ? (p.blobs.get(change.hash)?.length ?? reused.get(change.hash)!) : null;
            this.#db.run(
              `INSERT INTO entry (key, deleted, etag, hash, metadata, content, size) VALUES (?, 0, ?, ?, ?, ?, ?)
               ON CONFLICT (key) DO UPDATE SET deleted = 0, etag = excluded.etag, hash = excluded.hash,
                 metadata = excluded.metadata, content = excluded.content, size = excluded.size`,
              change.key,
              change.etag,
              change.hash,
              JSON.stringify(change.metadata),
              change.content ? 1 : 0,
              size,
            );
          }
          const sets: string[] = ["cursor = ?", "coverage = ?"];
          const params: SqlValue[] = [p.cursor, p.coverage];
          if (p.authority !== null) {
            sets.push("node_did = ?", "attested = 1", "not_before = ?", "expires_at = ?", "last_sync_at = ?");
            params.push(p.source.nodeDid, p.authority.notBefore, p.authority.expiresAt, p.at);
            // The attested retainUntil belongs to the retention grant the
            // request presented: if a setRetentionGrant raced the page, the
            // stored CID no longer matches and retain_until stays untouched
            // (null after the CID change) instead of reviving the previous
            // grant's window under a new CID.
            if (this.#row()!.retention_grant_cid === p.retentionGrantCid) {
              sets.push("retain_until = ?");
              params.push(p.authority.retainUntil);
              // A node-attested retention under a new retain grant supersedes a learned revocation of the old one.
              if (p.authority.retainUntil !== null) sets.push("retention_revoked = NULL");
            }
          }
          if (p.complete) {
            sets.push("last_complete_at = ?", "last_error = NULL");
            params.push(p.at);
          }
          if (p.promoteGrant !== null) {
            const g = p.promoteGrant;
            sets.push("grant_cid = ?", "grant_bytes = ?", "grant_audience = ?", "grant_issuer = ?", "grant_nbf = ?", "grant_exp = ?");
            params.push(g.cid, g.bytes, g.audience, g.issuer, g.notBefore, g.expiresAt);
            // Clear the pending slot only if it still holds the grant just validated.
            if (this.#row()!.pending_grant_cid === g.cid) {
              sets.push(
                "pending_grant_cid = NULL",
                "pending_grant_bytes = NULL",
                "pending_grant_audience = NULL",
                "pending_grant_issuer = NULL",
                "pending_grant_nbf = NULL",
                "pending_grant_exp = NULL",
                "pending_grant_error = NULL",
              );
            }
          }
          this.#db.run(`UPDATE replica SET ${sets.join(", ")} WHERE id = 1`, ...params);
          this.#faults.beforeCommit?.();
        });
      } catch (error) {
        // Revoked while this call wrote its blobs: the purge may already have
        // run, so remove them again (a failure leaves purge_pending for open).
        if (isReplicaError(error, ReplicaErrorCode.GRANT_REVOKED)) await this.#purgeContent().catch(() => undefined);
        // A page that wrote blobs but did not commit leaves them unreferenced: drop them now
        // when a quota is enforced, so on-disk bytes stay inside the budget.
        else if (this.#admit) await this.#collectLocked(t).catch(() => undefined);
        throw error;
      }
      this.#faults.afterCommit?.();
      // Blobs only the replaced or deleted entries referenced are free to go now.
      if (this.#admit) await this.#collectLocked(t);
    });
  }

  /** Unlink every blob not in `keep`, and every temp file. Only a missing directory counts as empty. */
  #unlinkBlobs(keep: Set<string>): Promise<number> {
    return unlinkBlobsIn(join(this.#pinnedDir, "blobs"), keep);
  }

  /** Whether any content file (a blob or a temp file) is on disk. */
  async #holdsContentFiles(): Promise<boolean> {
    const root = join(this.#pinnedDir, "blobs");
    for (const shard of await entriesOf(root)) {
      if ((await entriesOf(join(root, shard))).length > 0) return true;
    }
    return false;
  }

  async collectGarbage(t: LeaseToken): Promise<number> {
    return this.#mutate(() => this.#collectLocked(t));
  }

  /** `collectGarbage` for callers already inside the mutation hold (it cannot re-enter `#mutate`). */
  async #collectLocked(t: LeaseToken): Promise<number> {
    const release = this.#shared ? await acquireWritableMutation(this.#shared) : undefined;
    // The write lock is held across the unlinks, and the lease token is
    // checked under it: a paused former holder can never unlink a blob the
    // current holder just committed a reference to.
    try {
      this.#db.exec("BEGIN IMMEDIATE");
    } catch (error) {
      release?.();
      throw storageError(error, "Collecting unused content");
    }
    try {
      this.#checkLease(t);
      await this.#faults.afterGarbageCollectionBegin?.();
      const keep = new Set(
        this.#db.all<{ hash: string }>("SELECT DISTINCT hash FROM entry WHERE content = 1").map((row) => row.hash),
      );
      const removed = await this.#unlinkBlobs(keep);
      this.#db.exec("COMMIT");
      return removed;
    } catch (error) {
      try {
        this.#db.exec("ROLLBACK");
      } catch {
        // already rolled back
      }
      throw storageError(error, "Collecting unused content");
    } finally {
      release?.();
    }
  }

  async reset(t: LeaseToken, reason: string, options: { keepSource?: boolean } = {}): Promise<void> {
    await this.#mutate(async () => {
      await this.#write("Resetting the replica", () => {
        this.#checkLease(t);
        this.#db.run("DELETE FROM entry");
        this.#db.run(
          `UPDATE replica SET cursor = NULL, ${options.keepSource ? "" : "node_did = NULL, "}coverage = 'empty', last_sync_at = NULL,
             last_complete_at = NULL, last_error = NULL, last_reset = ?, generation = generation + 1 WHERE id = 1`,
          JSON.stringify({ at: new Date(this.#now()).toISOString(), reason }),
        );
      });
    });
    await this.collectGarbage(t);
    if (!this.#checkpoint()) {
      throw new ReplicaError(
        ReplicaErrorCode.BUSY,
        "The replica was reset, but another process is reading it, so its old pages are still in the write-ahead log. Run the reset again when that process ends.",
      );
    }
  }

  /**
   * Remove the source-created mirror layout under a live lease. Unknown files
   * are removed only when their exact preflight identities were approved.
   */
  async destroy(t: LeaseToken, options: {
    approvedUnknown?: readonly SqliteLayoutEntry[];
    expectedKnown?: readonly SqliteLayoutEntry[];
    expectedRoot?: { dev: string; ino: string };
    allowMissingDatabase?: boolean;
    allowAdapterFence?: boolean;
  } = {}): Promise<void> {
    await this.#mutate(async () => {
      const release = this.#shared ? await acquireWritableMutation(this.#shared) : undefined;
      try {
        this.#db.exec("BEGIN IMMEDIATE");
      } catch (error) {
        release?.();
        throw storageError(error, "Removing the replica");
      }
      try {
        this.#checkLease(t, { allowRevoked: true });
        const expected = this.#directoryFd === undefined ? this.#namedAncestors.at(-1) : fstatSync(this.#directoryFd, { bigint: true });
        if (!expected) {
          throw new ReplicaError(ReplicaErrorCode.RUNTIME_UNSUPPORTED, "Replica removal requires an opened or identity-checked directory.");
        }
        const assertDirectory = async (): Promise<BigIntStats> => {
          const current = await lstat(this.dir, { bigint: true });
          if (!current.isDirectory() || current.dev !== expected.dev || current.ino !== expected.ino) {
            throw new ReplicaError(ReplicaErrorCode.NOT_FOUND, "The replica directory changed during removal.");
          }
          return current;
        };
        const pinned = await assertDirectory();
        // A refused removal whose named path moved reports the move, as a changed directory does.
        const assertNamedPath = async (): Promise<void> => {
          for (const ancestor of this.#namedAncestors) {
            const current = await lstat(ancestor.path, { bigint: true });
            if (current.dev !== ancestor.dev || current.ino !== ancestor.ino) {
              throw new ReplicaError(ReplicaErrorCode.NOT_FOUND, "The replica ancestry changed during removal.");
            }
          }
          await assertDirectory();
        };
        // Holding the write lock: no other lease holder can mutate this store.
        await this.#assertPresent();
        try {
          await removeSqliteReplicaLayout(this.dir, {
            ...options,
            expectedRoot: options.expectedRoot ?? { dev: pinned.dev.toString(), ino: pinned.ino.toString() },
          });
        } catch (error) {
          await assertNamedPath();
          throw error;
        }
      } catch (error) {
        throw storageError(error, "Removing the replica");
      } finally {
        try {
          this.#db.exec("ROLLBACK");
        } catch {
          // Nothing was written.
        }
        release?.();
      }
    });
  }

  /**
   * Truncate the WAL so purged pages do not linger in it. TRUNCATE waits on
   * readers through busy_timeout; false when one still held it.
   */
  #checkpoint(): boolean {
    try {
      const result = this.#db.get<{ busy: number }>("PRAGMA wal_checkpoint(TRUNCATE)");
      return result === undefined || Number(result.busy) === 0;
    } catch (error) {
      throw storageError(error, "Checkpointing the replica");
    }
  }

  /**
   * Record the revocation (durable before this returns: reads are blocked
   * from here on, also after a restart), then purge. A purge that fails
   * keeps purge_pending set: status reports it and every open retries it.
   */
  async markRevoked(detail: string): Promise<void> {
    await this.#guardedWrite("Recording the revocation", () => {
      this.#db.run("DELETE FROM entry");
      // Bumping the lease token fences every outstanding writer.
      this.#db.run(
        `UPDATE replica SET revoked_detail = ?, cursor = NULL, coverage = 'empty', purge_pending = 1,
           lease_token = lease_token + 1, lease_holder = NULL, lease_expires_at = NULL, generation = generation + 1,
           last_error = ? WHERE id = 1`,
        detail,
        JSON.stringify({ at: new Date(this.#now()).toISOString(), code: ReplicaErrorCode.GRANT_REVOKED, message: detail }),
      );
    });
    this.#faults.afterPurgeMark?.();
    await this.#finishRevocationPurge().catch(() => undefined);
  }

  #finishRevocationPurge(): Promise<void> {
    return this.#mutate(() => this.#purgeContent());
  }

  /**
   * Inside a mutation section of a revoked replica: unlink every content
   * file and truncate the WAL. purge_pending is set first and cleared only
   * when both are done.
   */
  async #purgeContent(): Promise<void> {
    await this.#write("Starting the revocation purge", () => {
      this.#db.run("UPDATE replica SET purge_pending = 1 WHERE id = 1 AND revoked_detail IS NOT NULL");
    });
    try {
      await this.#unlinkBlobs(new Set());
    } catch (error) {
      throw storageError(error, "Purging revoked content");
    }
    if (!this.#checkpoint()) {
      throw new ReplicaError(ReplicaErrorCode.BUSY, "A reader holds the replica's write-ahead log; the purge finishes on the next open.");
    }
    await this.#write("Finishing the revocation purge", () => {
      this.#db.run("UPDATE replica SET purge_pending = 0 WHERE id = 1 AND revoked_detail IS NOT NULL");
    });
  }

  async recordError(e: ReplicaLastError): Promise<void> {
    await this.#guardedWrite("Recording the sync error", () => {
      this.#db.run("UPDATE replica SET last_error = ? WHERE id = 1", JSON.stringify(e));
    });
  }

  async get(key: string): Promise<LocalEntry | undefined> {
    this.#assertAccepting();
    try {
      const row = this.#db.get<EntryRow>("SELECT key, deleted, etag, hash, metadata, content FROM entry WHERE key = ?", key);
      return row === undefined ? undefined : entryOf(row);
    } catch (error) {
      throw storageError(error, "Reading the replica");
    }
  }

  async list(o: ListOpts): Promise<LocalEntry[]> {
    this.#assertAccepting();
    const where = ["deleted = 0"];
    const params: SqlValue[] = [];
    if (o.prefix !== undefined && o.prefix !== "") {
      where.push("key >= ?", "substr(key, 1, length(?)) = ?");
      params.push(o.prefix, o.prefix, o.prefix);
    }
    if (o.after !== undefined) {
      where.push("key > ?");
      params.push(o.after);
    }
    params.push(o.limit ?? -1);
    try {
      return this.#db
        .all<EntryRow>(
          `SELECT key, deleted, etag, hash, metadata, content FROM entry WHERE ${where.join(" AND ")} ORDER BY key LIMIT ?`,
          ...params,
        )
        .map(entryOf);
    } catch (error) {
      throw storageError(error, "Listing the replica");
    }
  }

  async pendingRepairs(limit: number): Promise<Array<Extract<LocalEntry, { deleted: false }>>> {
    return this.#db
      .all<EntryRow>(
        "SELECT key, deleted, etag, hash, metadata, content FROM entry WHERE deleted = 0 AND content = 0 ORDER BY key LIMIT ?",
        limit,
      )
      .map(entryOf) as Array<Extract<LocalEntry, { deleted: false }>>;
  }

  async readContent(hash: string): Promise<Uint8Array | undefined> {
    if (!isHash(hash)) return undefined;
    try {
      return new Uint8Array(await readFile(this.#blobPath(hash)));
    } catch (error) {
      if (errnoOf(error) === "ENOENT") return undefined;
      throw storageError(error, "Reading replica content");
    }
  }

  async status(now = this.#now()): Promise<ReplicaStatus> {
    const state = await this.open();
    if (state === null) throw new ReplicaError(ReplicaErrorCode.NOT_FOUND, "The replica has not been created.");
    const row = this.#row()!;
    const counts = this.#db.get<{ keys: number; missing: number; tombstones: number; bytes: number }>(
      `SELECT
         COALESCE(SUM(deleted = 0), 0) AS keys,
         COALESCE(SUM(deleted = 0 AND content = 0), 0) AS missing,
         COALESCE(SUM(deleted = 1), 0) AS tombstones,
         COALESCE(SUM(CASE WHEN deleted = 0 AND content = 1 THEN size ELSE 0 END), 0) AS bytes
       FROM entry`,
    )!;
    const { retentionRevoked: _retentionRevoked, ...authority } = effectiveAuthority({
      window: state.authority,
      grant: state.grant,
      revoked: state.revoked,
      retentionRevoked: state.retentionRevoked,
      policy: state.config.localReadPolicy,
      now,
    });
    return {
      name: state.config.name,
      replicaId: state.config.replicaId,
      source: { host: state.config.host, nodeDid: state.nodeDid, space: state.config.space, prefix: state.config.prefix },
      device: {
        did: state.config.deviceDid,
        delegationCid: state.grant?.cid ?? null,
        pendingDelegationCid: state.pendingGrant?.cid ?? null,
        pendingDelegationError: state.pendingGrantError,
      },
      authority: {
        ...authority,
        localReadPolicy: state.config.localReadPolicy,
        retentionGrantCid: state.config.retentionGrantCid,
        revokedDetail: state.revoked,
        retentionRevokedDetail: state.retentionRevoked,
      },
      consistency: "observed",
      coverage: state.coverage,
      lastSyncAt: state.lastSyncAt,
      lastCompleteAt: state.lastCompleteAt,
      counts: { keys: Number(counts.keys), contentMissing: Number(counts.missing), tombstones: Number(counts.tombstones) },
      bytes: Number(counts.bytes),
      durability: DURABILITY,
      syncing: row.lease_holder !== null && row.lease_expires_at !== null && row.lease_expires_at > now,
      purgePending: row.purge_pending === 1,
      lastError: state.lastError,
      lastReset: state.lastReset,
    };
  }

  close(): Promise<void> {
    if (this.#closePromise) return this.#closePromise;
    this.#closing = true;
    this.#closePromise = (async () => {
      if (this.#activeMutations !== 0) {
        await new Promise<void>((resolve) => { this.#drained = resolve; });
      }
      this.#closed = true;
      const fd = this.#directoryFd;
      this.#directoryFd = undefined;
      if (this.#shared) {
        sharedStores.unregister(this);
        releaseWritable(this.#shared);
      } else {
        if (fd !== undefined) pinnedDirectories.unregister(this);
        try { this.#database.close(); } finally { if (fd !== undefined) closeSync(fd); }
      }
    })();
    return this.#closePromise;
  }
}
