import { canonicalize, canonicalMailbox, toBase64Url } from "@tinycloud/share-envelope";
import type { SenderShareRecord } from "./history.js";

export type ShareNotifyState = "delivered" | "already-delivered" | "partial-failure";

export interface ShareNotifyResult {
  readonly protocol: "tinycloud-share";
  readonly version: 1;
  readonly shareId: string;
  readonly state: ShareNotifyState;
  readonly idempotencyKey: string;
  readonly attempts: number;
  readonly retryable?: boolean;
  readonly reason?: "delivery-window-expired";
}

export interface ShareNotifyInput {
  readonly shareId: string;
  readonly recipient: string;
  readonly record?: SenderShareRecord;
  readonly idempotencyKey?: string;
  readonly signal?: AbortSignal;
}

export interface ShareDeliveryAdapter {
  /** The server must deduplicate this key before any message is sent. */
  deliver(input: ShareNotifyInput): Promise<"delivered" | "already-delivered">;
}

export class ShareNotifyError extends Error {
  readonly code = "delivery-failed" as const;
  constructor(
    message = "share delivery did not complete",
    readonly reason?: "delivery-window-expired",
  ) {
    super(message);
    this.name = "ShareNotifyError";
  }
}

/**
 * Match a delivery address against the recipient constraint recorded when the
 * share was created. Both sides compare in canonical mailbox form, which is
 * the only form the credential issuer accepts.
 */
export function recipientMatchesShareRecord(record: SenderShareRecord, recipient: string): boolean {
  const matcher = record.recipientMatcher;
  const mailbox = canonicalMailbox(recipient);
  if (mailbox === undefined) return false;
  if (matcher.kind === "exactEmail") return canonicalMailbox(matcher.value)?.email === mailbox.email;
  if (matcher.kind === "emailDomain") return mailbox.domain === matcher.value;
  return false;
}
/** The sender can authorize a fresh invitation only until this persisted deadline. */
export function shareDeliveryWindowExpiresAt(record: SenderShareRecord): number {
  const expiresAt = Math.min(Date.parse(record.expiresAt), Date.parse(record.registeredAt) + 5 * 60 * 1000);
  if (!Number.isFinite(expiresAt)) throw new ShareNotifyError("share delivery history has invalid timestamps");
  return expiresAt;
}

/**
 * Delivery is deliberately separate from publication. A failed notification
 * never causes a second envelope or link to be minted.
 */
export async function notifyShare(input: {
  readonly shareId: string;
  readonly recipient: string;
  readonly record?: SenderShareRecord;
  readonly adapter: ShareDeliveryAdapter;
  readonly idempotencyKey?: string;
  readonly maxAttempts?: number;
  readonly signal?: AbortSignal;
  /** Check the persisted delivery window locally before calling the adapter. */
  readonly checkDeliveryWindow?: boolean;
}): Promise<ShareNotifyResult> {
  const mailbox = canonicalMailbox(input.recipient);
  if (!input.shareId || mailbox === undefined) throw new ShareNotifyError("recipient is invalid");
  // Deliver to, match and key on the canonical mailbox: a typed `Foo@x.com`
  // is the same recipient as the stored `foo@x.com`.
  const recipient = mailbox.email;
  if (input.record !== undefined && !recipientMatchesShareRecord(input.record, recipient)) {
    throw new ShareNotifyError("recipient does not match the stored share target");
  }
  const idempotencyKey = input.idempotencyKey ?? await defaultIdempotencyKey(input.shareId, recipient);
  const attemptsLimit = input.maxAttempts ?? 3;
  if (!Number.isSafeInteger(attemptsLimit) || attemptsLimit < 1 || attemptsLimit > 8) throw new ShareNotifyError("maxAttempts is invalid");
  if (input.signal?.aborted) throw new ShareNotifyError("share delivery was cancelled");
  if (input.checkDeliveryWindow && input.record !== undefined && shareDeliveryWindowExpiresAt(input.record) <= Date.now()) {
    return {
      protocol: "tinycloud-share", version: 1, shareId: input.shareId,
      state: "partial-failure", idempotencyKey, attempts: 1,
      retryable: false, reason: "delivery-window-expired",
    };
  }
  let attempts = 0;
  while (attempts < attemptsLimit) {
    if (input.signal?.aborted) throw new ShareNotifyError("share delivery was cancelled");
    attempts += 1;
    try {
      const state = await input.adapter.deliver({ shareId: input.shareId, recipient, idempotencyKey, ...(input.record === undefined ? {} : { record: input.record }), ...(input.signal === undefined ? {} : { signal: input.signal }) });
      return {
        protocol: "tinycloud-share", version: 1, shareId: input.shareId,
        state: state === "delivered" && input.record?.deliveredRecipients?.includes(recipient) ? "already-delivered" : state,
        idempotencyKey, attempts,
      };
    } catch (error) {
      if (error instanceof ShareNotifyError && error.reason === "delivery-window-expired") {
        return {
          protocol: "tinycloud-share", version: 1, shareId: input.shareId,
          state: "partial-failure", idempotencyKey, attempts,
          retryable: false, reason: "delivery-window-expired",
        };
      }
      // A refused authorization (the node's HTTP 400 and 422 are one refusal, carrying this code) is final, like a 401 or 403.
      const refused = error !== null && typeof error === "object" && "code" in error && error.code === "delivery-authorization-invalid";
      if (refused || (error !== null && typeof error === "object" && "status" in error && (error.status === 401 || error.status === 403))) {
        return {
          protocol: "tinycloud-share", version: 1, shareId: input.shareId,
          state: "partial-failure", idempotencyKey, attempts, retryable: false,
        };
      }
    }
  }
  return { protocol: "tinycloud-share", version: 1, shareId: input.shareId, state: "partial-failure", idempotencyKey, attempts, retryable: true };
}

/** Bind the default retry key to the canonical recipient as well as the share. */
async function defaultIdempotencyKey(shareId: string, recipient: string): Promise<string> {
  const canonicalRecipient = canonicalize(recipient.trim().toLowerCase());
  const digest = new Uint8Array(await crypto.subtle.digest(
    "SHA-256",
    new TextEncoder().encode(canonicalRecipient),
  ));
  return `tinycloud-share:${shareId}:${toBase64Url(digest)}`;
}
